// NOTE: Stagger wrapper — animates children one after another
'use client';

import { useRef } from 'react';

import { LazyMotion, domAnimation, m, useInView } from 'motion/react';
import type { Variants } from 'motion/react';

import { EASE } from '@/lib/animation-config';

interface StaggerChildrenProps {
  children: React.ReactNode;
  /** Delay between each child (seconds) */
  staggerDelay?: number;
  /** Delay before first child starts (seconds) */
  initialDelay?: number;
  /** Amount of element visible before triggering (0-1) */
  amount?: number;
  /** Only animate once */
  once?: boolean;
  /** Additional className */
  className?: string;
  /** Trigger on page load instead of scroll */
  onLoad?: boolean;
}

export function StaggerChildren({
  children,
  staggerDelay = 0.12,
  initialDelay = 0.1,
  amount = 0.2,
  once = true,
  className,
  onLoad = false,
}: Readonly<StaggerChildrenProps>) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once, amount });

  const containerVariants: Variants = {
    hidden: { opacity: 1 },
    visible: {
      opacity: 1,
      transition: {
        delayChildren: initialDelay,
        staggerChildren: staggerDelay,
      },
    },
  };

  return (
    <LazyMotion features={domAnimation}>
      <m.div
        ref={ref}
        initial="hidden"
        animate={onLoad || isInView ? 'visible' : 'hidden'}
        variants={containerVariants}
        className={className}
      >
        {children}
      </m.div>
    </LazyMotion>
  );
}

// NOTE: Child item to use inside StaggerChildren
// Each child defines its own hidden/visible animation
interface StaggerItemProps {
  children: React.ReactNode;
  className?: string;
  /** Custom variants for this item */
  variants?: Variants;
}

const defaultItemVariants: Variants = {
  hidden: {
    opacity: 0,
    y: 20,
  },
  visible: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.5,
      ease: EASE.expOut,
    },
  },
};

export function StaggerItem({
  children,
  className,
  variants = defaultItemVariants,
}: Readonly<StaggerItemProps>) {
  return (
    <LazyMotion features={domAnimation}>
      <m.div variants={variants} className={className}>
        {children}
      </m.div>
    </LazyMotion>
  );
}
